ALTER TABLE public.hiring_applications DROP CONSTRAINT IF EXISTS hiring_applications_status_check;
ALTER TABLE public.hiring_applications ADD CONSTRAINT hiring_applications_status_check CHECK(status IN ('submitted','reviewing','interview','hired','declined'));
ALTER TABLE public.hiring_applications ADD COLUMN interview_date date, ADD COLUMN interview_time text CHECK(interview_time IN ('09:00','12:00','15:00','18:00'));
CREATE OR REPLACE FUNCTION public.review_application(_id uuid,_status text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE applicant uuid; BEGIN IF NOT public.has_role(auth.uid(),'admin') THEN RAISE EXCEPTION 'Admin access required'; END IF; IF _status NOT IN ('reviewing','interview','hired','declined') THEN RAISE EXCEPTION 'Invalid review status'; END IF; SELECT user_id INTO applicant FROM public.hiring_applications WHERE id=_id FOR UPDATE; IF applicant IS NULL THEN RAISE EXCEPTION 'Application not found'; END IF; UPDATE public.hiring_applications SET status=_status WHERE id=_id; IF _status='hired' THEN INSERT INTO public.user_roles(user_id,role) VALUES(applicant,'cleaner') ON CONFLICT(user_id,role) DO NOTHING; END IF; END $$;
CREATE FUNCTION public.choose_interview_time(_id uuid,_date date,_time text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF _time NOT IN ('09:00','12:00','15:00','18:00') THEN RAISE EXCEPTION 'Choose 9am, 12pm, 3pm or 6pm'; END IF; IF _date IS NULL OR _date < (now() AT TIME ZONE 'America/New_York')::date OR _date > (now() AT TIME ZONE 'America/New_York')::date + 60 THEN RAISE EXCEPTION 'Choose a date within the next 60 days'; END IF; UPDATE public.hiring_applications SET interview_date=_date, interview_time=_time WHERE id=_id AND user_id=auth.uid() AND status='interview'; IF NOT FOUND THEN RAISE EXCEPTION 'No interview request found'; END IF; END $$;
REVOKE ALL ON FUNCTION public.choose_interview_time(uuid,date,text) FROM public, anon;
GRANT EXECUTE ON FUNCTION public.choose_interview_time(uuid,date,text) TO authenticated;